package ru.nartov.lab7;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class StudentControllerTest {@Autowired MockMvc mvc;@Test void listPageRenders() throws Exception {mvc.perform(get("/list")).andExpect(status().isOk()).andExpect(view().name("list-students")).andExpect(model().attributeExists("students"));}}
